function stats(attempts,metric) {
  const values=attempts.map(item=>item.metrics?.[metric]).filter(Number.isFinite).sort((a,b)=>a-b),n=values.length;
  return {
    n,attempted:attempts.length,failedAttempts:attempts.filter(item=>item.status!=='PASS').length,
    missingOrNonFinite:attempts.length-n,includesFailedAttempts:true,
    min:n?values[0]:null,
    median:n?(values[Math.floor((n-1)/2)]+values[Math.floor(n/2)])/2:null,
    max:n?values[n-1]:null
  };
}
